// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;

    function setUp() public {
        c = new C();
        attacker = new ReentrantAttacker(c);
    }

    function testFuzz_property(uint256 depositAmount, uint256 probe) public {
        vm.assume(depositAmount > 0);
        attacker.setProbe(probe);
        vm.deal(address(attacker), depositAmount);
        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        // withdrawAll from the attacker; during the payout the attacker re-enters
        // and reads c.credit(address(this)). In P credit is already zeroed before
        // the call; in M it still equals depositAmount.
        vm.prank(address(attacker));
        c.withdrawAll();

        assertTrue(attacker.seenCreditDuringPayout() == 0);
    }
}

contract ReentrantAttacker {
    C c;
    uint256 probe;
    uint256 seen;

    constructor(C _c) { c = _c; }
    function setProbe(uint256 p) external { probe = p; }
    function seenCreditDuringPayout() external view returns (uint256) { return seen; }

    receive() external payable {
        seen = c.credit(address(this));
        // consume the fuzzed probe so the payout path is exercised
        require(probe >= 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 ether, 100 ether);
        Actor actor = new Actor(c);
        vm.deal(address(actor), amount);
        actor.doDeposit(amount);
        bool ok;
        try actor.doWithdraw() { ok = true; } catch { ok = false; }
        // General rule: if the withdraw did NOT succeed, the caller's credit is untouched;
        // if it succeeded, credit is zero AND the caller actually received the funds.
        assertTrue(ok ? c.credit(address(actor)) == 0 && address(actor).balance >= amount
                      : c.credit(address(actor)) == amount && address(c).balance == amount);
    }
}

contract Actor {
    C c;
    constructor(C c_) { c = c_; }
    function doDeposit(uint256 amt) external { c.deposit{value: amt}(); }
    function doWithdraw() external { c.withdrawAll(); }
    fallback() external payable { revert(); }
}

